### Generating a Day

```xiom
fn pick_condition(temp: Int) -> WeatherCondition {
  if temp > 35 { return WeatherCondition.Sunny; };
  if temp > 25 { return WeatherCondition.PartlyCloudy; };
  if temp > 15 { return WeatherCondition.Cloudy; };
  if temp > 5 { return WeatherCondition.Rainy; };
  WeatherCondition.Snowy
}

fn generate_day(day_name: Str, season_temp: Int) -> DayForecast {
  let variation = random.range(-8, 9);
  let high = season_temp + variation;
  let low = high - random.range(3, 10);
  let cond = pick_condition(high);
  let hum = if cond == WeatherCondition.Rainy || cond == WeatherCondition.Stormy
    { random.range(70, 96) }
    else { random.range(30, 71) };
  let wind = random.range(0, 31);

  DayForecast{ day: day_name, temp_high: high, temp_low: low, humidity: hum, condition: cond, wind_speed: wind }
}
```

### Generating the Week

```xiom
fn generate_week() -> Vec[DayForecast] {
  let days: Vec[Str] = Vec[Str].new();
  days.push("Monday"); days.push("Tuesday"); days.push("Wednesday");
  days.push("Thursday"); days.push("Friday"); days.push("Saturday"); days.push("Sunday");

  let base_temp = 22;
  let mut forecast: Vec[DayForecast] = Vec[DayForecast].new();
  let mut i = 0;
  while i < days.len() {
    let day = days.get(i).unwrap();
    forecast.push(generate_day(day, base_temp));
    i += 1;
  };
  forecast
}
```

### Analysis Functions

```xiom
fn find_highest(forecast: &Vec[DayForecast]) -> DayForecast {
  let mut best = forecast.get(0).unwrap();
  let mut i = 1;
  while i < forecast.len() {
    let d = forecast.get(i).unwrap();
    if d.temp_high > best.temp_high { best = d; };
    i += 1;
  };
  best
}

fn calculate_average_high(forecast: &Vec[DayForecast]) -> Int {
  let mut sum = 0;
  let mut i = 0;
  while i < forecast.len() {
    sum += forecast.get(i).unwrap().temp_high;
    i += 1;
  };
  sum / forecast.len()
}
```

