solution:
enum Weather {
  Sunny;
  Cloudy;
  Rainy;
  Snowy;
}

type Day {
  name: Str;
  temp_high: Int;
  temp_low: Int;
  condition: Weather;
}

fn condition_icon(w: Weather) -> Str {
  match w {
    Weather.Sunny => "Sunny",
    Weather.Cloudy => "Cloudy",
    Weather.Rainy => "Rainy",
    Weather.Snowy => "Snowy",
  }
}

fn make_day(name: Str, base_temp: Int) -> Day {
  let high = base_temp + random.range(-5, 6);
  let low = high - random.range(3, 9);
  let cond = if high > 25
    { Weather.Sunny }
    else if high > 15
    { Weather.Cloudy }
    else if high > 5
    { Weather.Rainy }
    else { Weather.Snowy };
  Day{ name: name, temp_high: high, temp_low: low, condition: cond }
}

fn find_warmest(week: &Vec[Day]) -> Str {
  let mut best = week.get(0).unwrap();
  let mut i = 1;
  while i < week.len() {
    let d = week.get(i).unwrap();
    if d.temp_high > best.temp_high { best = d; };
    i += 1;
  };
  best.name
}

fn avg_high(week: &Vec[Day]) -> Int {
  let mut sum = 0;
  let mut i = 0;
  while i < week.len() {
    sum += week.get(i).unwrap().temp_high;
    i += 1;
  };
  sum / week.len()
}

fn print_day(d: &Day) {
  io.println(d.name);
  io.println(d.temp_high);
  io.println(d.temp_low);
  io.println(condition_icon(d.condition));
}

fn main() -> Int {
  let mut week: Vec[Day] = Vec[Day].new();
  week.push(make_day("Saturday", 24));
  week.push(make_day("Sunday", 24));
  print_day(week.get(0).unwrap());
  print_day(week.get(1).unwrap());
  io.println(find_warmest(&week));
  io.println(avg_high(&week));
  return 0;
}
